const KEY='mason-trainer-v1';
const empty=()=>({days:{},spent:[],claims:{},settings:{budget:'10',local:'A special local outing',super:'A bigger day out',legendary:'Our big adventure',ready:'08:00',start:'19:30',lights:'20:00'}});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||empty()}catch{state=empty()}
let view='today',date=today();
function today(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dt(s){return new Date(s+'T12:00:00')}
function shift(s,n){let d=dt(s);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function monday(s){return shift(s,-((dt(s).getDay()+6)%7))}
function weekend(){return [0,6].includes(dt(date).getDay())}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function day(s=date){return state.days[s]||{awards:[],checks:{},mode:'homework',chore:'0',brain:'0',off:false}}
function editable(){if(!state.days[date])state.days[date]=day();return state.days[date]}
function off(){return weekend()||day().off}
function sum(){return Object.values(state.days).reduce((n,d)=>n+d.awards.length,0)}
function bank(){return sum()-state.spent.reduce((n,r)=>n+r.cost,0)}
function weekly(start=monday(date)){return Array.from({length:7},(_,i)=>day(shift(start,i)).awards.length).reduce((a,b)=>a+b,0)}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function toast(s){let e=document.querySelector('#toast');e.textContent=s;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}
const missions=[['morning','☀','Ready for Adventure','Get dressed, fuel up & launch your day','#fff0be'],['brain','⚡','Train Your Brain','A little learning goes a long way','#eee5fc'],['gear','🎒','Unpack Your Gear','Give your school things a home','#e3edd9'],['center','🌱','Care for Your Pokémon Center','One little job to help our home','#f9e5d8'],['night','☾','Recharge Your Pokémon','Get clean, cozy & ready to rest','#e0eafb']];
const chores=[['Restore the Training Ground','Put toys away in one agreed play area; leave walking paths clear.'],['Sort the Trainer Uniforms','Match socks OR put away a small pile of your folded clothes.'],['Prepare the Team Table','Set out napkins, utensils, and unbreakable cups.'],['Refresh the Center','Wipe the table with a damp cloth and pick up crumbs.'],['Organize the Pokédex Library','Put loose books away and tidy one small section.'],['Care for the Grass Types','Water designated plants using the amount a grown-up shows you.']];
const brains=[['Explore the Pokédex','Read or share a book for 15 minutes. Tell a grown-up one thing about it. Comics and Pokémon books count!'],['Power Up Your Math','Practice school math for 10 minutes with a game, cards, or a short activity.'],['Write a Trainer Report','Write 3–5 sentences about a Pokémon, your day, or an adventure. Add a picture if you like.'],['Solve a Gym Challenge','Spend 15 minutes on a puzzle, logic game, or building challenge that uses a plan or solves a problem.']];
function steps(id){if(id==='morning')return [['Put on your Trainer gear','Get dressed, including socks. Put pajamas in their spot.'],['Fuel up','Eat breakfast and take dishes to the sink.'],['Make your smile sparkle','Brush teeth for two minutes. A parent can check or help.'],...off()?[]:[['Check your adventure pack','Pack folder and assigned items; add lunch and filled water bottle once ready.'],['Report to the launch pad',`Shoes and coat on; backpack at the door. Ready at ${state.settings.ready}.`]]];
if(id==='gear')return off()?[['Check your gear station','Put away the shoes, coat, and bag you used; empty food containers. If no gear was used, check backpack, shoes, and coat are in place.']]:[['Park your adventure pack','Put your backpack in its designated spot.'],['Deliver your Trainer mail','Give papers and notes to a grown-up. Put homework in your work spot.'],['Unload your supplies','Lunchbox and water bottle to the counter; wrappers in the trash; containers by the sink.'],['Store your Trainer gear','Put shoes away and hang up your coat.']];
if(id==='night')return [['Power down your Pokédex','Turn off and put away devices when the bedtime routine begins.'],['Freshen up for tomorrow','Use the bathroom and wash up. Bath or shower on designated nights.'],['Change into sleep gear','Pajamas on; dirty clothes in the hamper.'],['Polish your Pokémon smile','Brush teeth for two minutes, with help as needed.'],['Enter your recharge station',`Choose a book or quiet cuddle, then settle into bed. Lights-out at ${state.settings.lights}.`]];
if(id==='center')return [chores[Number(day().chore)||0]];
if(off())return [brains[Number(day().brain)||0]];
return day().mode==='homework'?[['Complete your assigned homework','Use an honest effort. Include reading if your teacher requires it.']]:[brains[0]]}
function modal(html){document.querySelector('#dialogContent').innerHTML=html;document.querySelector('#dialog').showModal()}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const n=day().awards.length,w=weekly();let html='';
if(view==='today')html=`<div class="topline"><div><h2>Your daily missions</h2><div class="muted">Five small wins. One awesome Trainer.</div></div><div class="datebar"><button id="prev" aria-label="Previous day">‹</button><input type="date" id="date" value="${date}" max="${today()}" aria-label="Mission date"><button id="next" aria-label="Next day" ${date>=today()?'disabled':''}>›</button></div></div><div class="dashboard"><div><label class="muted"><input type="checkbox" id="off" ${day().off?'checked':''} ${weekend()?'disabled':''}> ${weekend()?'Weekend mini missions active':'School break / no school today'}</label><div class="missions" style="margin-top:12px">${missions.map(([id,icon,title,sub,tint])=>`<button class="card mission ${day().awards.includes(id)?'done':''}" data-mission="${id}"><span class="icon" style="--tint:${tint}">${icon}</span><span><h3>${title}</h3><p>${sub}</p></span><span class="right"><span class="chip">${day().awards.includes(id)?'EARNED':'1 POINT'}</span>${day().awards.includes(id)?'✓ Complete':'Open →'}</span></button>`).join('')}</div></div><aside class="side"><div class="card summary"><div class="tiny-label">TODAY’S POWER</div><div class="score">${n}<small> / 5</small></div><div class="track"><div style="width:${n*20}%"></div></div><p>${n===5?'All missions complete. Amazing work!':'Every mission is a chance to grow.'}</p><hr style="opacity:.15"><div class="tiny-label">THIS WEEK: ${w} / 25</div><p>${w>=25?'Gym Badge & Target reward unlocked!':`${25-w} more points to your Gym Badge.`}</p></div><div class="card bank-mini"><div class="tiny-label">ADVENTURE SAVINGS</div><strong>${bank()}</strong><div class="muted">Poké Points in your bank</div><button id="toBank">Explore rewards →</button></div></aside></div>`;
if(view==='week'){let start=monday(date);let weeks=[...new Set(Object.keys(state.days).map(monday))].sort().reverse();html=`<div class="topline"><div><h2>Your Gym Badge journey</h2><div class="muted">25 points unlocks a badge and a small Target toy. Your bank keeps every point.</div></div><input type="date" id="date" value="${date}" max="${today()}" aria-label="Choose week by date"></div><div class="card"><div class="badge">⬡</div><h2>Week of ${esc(dt(start).toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</h2><p>${w} / 35 points earned · ${Math.max(0,25-w)} to unlock your reward</p><div class="weekrow">${Array.from({length:7},(_,i)=>{let d=shift(start,i);return `<div class="day">${['MON','TUE','WED','THU','FRI','SAT','SUN'][i]}<strong>${day(d).awards.length}/5</strong></div>`}).join('')}</div><p class="muted">Target toy budget: $${esc(state.settings.budget)}. Claiming this reward costs no bank points.</p><button id="claim" ${w<25||state.claims[start]?'disabled':''}>${state.claims[start]?'✓ Target reward received':w>=25?'Mark Target reward received':'Keep training to unlock'}</button></div><div class="card history"><h3>Badge collection</h3>${weeks.filter(k=>weekly(k)>=25).map(k=>`<p><span>⬡ Week of ${esc(k)}</span><span>${weekly(k)} points · ${state.claims[k]?'Reward received':'Reward ready'}</span></p>`).join('')||'<p>Your first Gym Badge is waiting. You’ve got this!</p>'}</div>`}
if(view==='bank')html=`<div class="topline"><div><h2>Your next big adventure</h2><div class="muted">Spend a little now or save for something legendary.</div></div><h2>✦ ${bank()} <small>points</small></h2></div><div class="grid3">${[['local','🌳','Local Adventure',100],['super','🎡','Super Adventure',200],['legendary','🏔','Legendary Adventure',300]].map(([id,icon,title,cost])=>`<div class="card reward"><div class="emoji">${icon}</div><h3>${title}</h3><p>${esc(state.settings[id])}</p><div class="price">${cost} <small style="font:12px sans-serif">POINTS</small></div><div class="track" style="background:#e9eadb"><div style="width:${Math.min(100,bank()/cost*100)}%;background:#5c8b5b"></div></div><p>${bank()>=cost?'Ready when your family is!':`${cost-bank()} more points to go`}</p><button data-redeem="${id}" ${bank()<cost?'disabled':''}>${bank()>=cost?'Redeem with a grown-up':'Keep saving'}</button></div>`).join('')}</div><div class="card history"><h3>Adventure journal</h3><div class="muted">${sum()} points earned − ${sum()-bank()} spent = ${bank()} saved</div>${state.spent.slice().reverse().map(r=>`<p><span>${esc(r.label)}<br><small>${esc(r.date)}</small></span><b>−${r.cost}</b></p>`).join('')||'<p>Your first adventure is still ahead. Every earned point stays saved until you spend it.</p>'}</div>`;
document.querySelector('#content').innerHTML=html;bind()}
function bind(){document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>openMission(b.dataset.mission));let $=s=>document.querySelector(s);if($('#date'))$('#date').onchange=e=>{if(e.target.value&&e.target.value<=today()){date=e.target.value;render()}};if($('#prev'))$('#prev').onclick=()=>{date=shift(date,-1);render()};if($('#next'))$('#next').onclick=()=>{if(date<today())date=shift(date,1);render()};if($('#off'))$('#off').onchange=e=>{editable().off=e.target.checked;save();render()};if($('#toBank'))$('#toBank').onclick=()=>{view='bank';render()};if($('#claim'))$('#claim').onclick=()=>{if(weekly()>=25&&!state.claims[monday(date)]){state.claims[monday(date)]=true;save();render();toast('Target reward recorded. Your savings stay!')}};document.querySelectorAll('[data-redeem]').forEach(b=>b.onclick=()=>redeem(b.dataset.redeem))}
function openMission(id){let m=missions.find(m=>m[0]===id),d=day(),earned=d.awards.includes(id),ss=steps(id);let selector=id==='center'?`<label class="field">Choose one job together<select id="choice">${chores.map((x,i)=>`<option value="${i}" ${d.chore==i?'selected':''}>${x[0]}</option>`).join('')}</select></label>`:id==='brain'?off()?`<label class="field">Choose one Brain Training mission<select id="choice">${brains.map((x,i)=>`<option value="${i}" ${d.brain==i?'selected':''}>${x[0]}</option>`).join('')}</select></label>`:`<label class="field">Today’s school routine<select id="mode"><option value="homework" ${d.mode==='homework'?'selected':''}>Assigned homework</option><option value="reading" ${d.mode==='reading'?'selected':''}>No homework: read for 15 minutes</option></select></label>`:'';
modal(`<div class="eyebrow">${off()?'WEEKEND / BREAK MISSION':'DAILY TRAINER MISSION'}</div><h2>${m[1]} ${m[2]}</h2><p>${id==='night'?`Routine starts at ${esc(state.settings.start)}. Earn the point for completing the routine and settling into bed; falling asleep is not required. Bathroom trips and reassurance never erase a point.`:id==='brain'?'Honest effort counts. Ask for help. A grown-up can agree on a stopping point if work becomes too hard. No extra worksheets after homework.':id==='center'?'A grown-up offers two choices; pick one and agree what finished means. Aim for 5–10 minutes. Choose a different task from unpacking your school gear.':id==='gear'?'After snack, reset your gear. Adults wash containers and manage paperwork deadlines.':'Reminders and help are allowed. Breakfast means following the routine, not eating a set amount.'}</p>${earned?'<div class="notice">✓ Point already earned. Great work! Earned points are never taken away.</div>':selector+ss.map((s,i)=>`<label class="check"><input type="checkbox" data-step="${i}" ${(d.checks[id]||[]).includes(i)?'checked':''}><span><strong>${esc(s[0])}</strong>${esc(s[1])}</span></label>`).join('')+`<button class="primary" id="award">Complete mission · +1 Poké Point</button><p class="muted">All steps together earn one point. A grown-up checks the mission with you.</p>`}`);
let choice=document.querySelector('#choice');if(choice)choice.onchange=e=>{editable()[id==='center'?'chore':'brain']=e.target.value;editable().checks[id]=[];save();document.querySelector('#dialog').close();openMission(id)};let mode=document.querySelector('#mode');if(mode)mode.onchange=e=>{editable().mode=e.target.value;editable().checks[id]=[];save();document.querySelector('#dialog').close();openMission(id)};
document.querySelectorAll('[data-step]').forEach(b=>b.onchange=()=>{editable().checks[id]=[...document.querySelectorAll('[data-step]:checked')].map(x=>Number(x.dataset.step));save()});let a=document.querySelector('#award');if(a)a.onclick=()=>{if(document.querySelectorAll('[data-step]:checked').length!==ss.length){toast('Check each step with your grown-up first.');return}if(date>today()||editable().awards.includes(id))return;editable().awards.push(id);save();document.querySelector('#dialog').close();render();toast('✦ +1 Poké Point! Nice work, Trainer!')};}
function redeem(id){let cost={local:100,super:200,legendary:300}[id];modal(`<h2>Ready for an adventure?</h2><p><b>${esc(state.settings[id])}</b></p><p>With a grown-up, confirm the outing, budget, and date. Redeeming costs ${cost} points and leaves ${bank()-cost} in your bank. Weekly Target rewards continue.</p><button class="primary" id="confirmRedeem">Grown-up confirms · spend ${cost} points</button>`);document.querySelector('#confirmRedeem').onclick=()=>{if(bank()<cost)return;state.spent.push({id:crypto.randomUUID(),label:state.settings[id],cost,date:today()});save();document.querySelector('#dialog').close();render();toast('Adventure redeemed. Have a wonderful time!')}}
function settings(){modal(`<h2>Parent tools</h2><p>Make the adventure your own. These tools are for family use; this is not a password-protected parent lock.</p><form id="prefs">${[['budget','Target toy budget ($)','number'],['ready','Ready for school','time'],['start','Bedtime routine starts','time'],['lights','Lights-out','time'],['local','100-point Local Adventure','text'],['super','200-point Super Adventure','text'],['legendary','300-point Legendary Adventure','text']].map(([id,label,type])=>`<label class="field">${label}<input name="${id}" type="${type}" value="${esc(state.settings[id])}" ${type==='number'?'min="0" max="999"':''} required></label>`).join('')}<button class="primary">Save settings</button></form><div class="notice">Progress stays in this browser. Export regularly. To move to another device, import your backup there. Import replaces that browser’s progress.</div><p><button id="export">Export backup</button> <button id="import">Import backup</button><input id="file" type="file" accept="application/json" hidden></p>`);document.querySelector('#prefs').onsubmit=e=>{e.preventDefault();state.settings=Object.fromEntries(new FormData(e.target));save();document.querySelector('#dialog').close();render();toast('Adventure settings saved')};document.querySelector('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download=`mason-trainer-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};document.querySelector('#import').onclick=()=>document.querySelector('#file').click();document.querySelector('#file').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());validate(v);if(!confirm('Replace progress on this browser with this backup? Export your current progress first if needed.'))return;state=v;save();document.querySelector('#dialog').close();render();toast('Backup imported')}catch{toast('That file is not a valid Trainer backup.')}}}
function validate(v){if(!v||typeof v.days!=='object'||!Array.isArray(v.spent)||typeof v.claims!=='object'||!v.settings)throw Error();for(let [k,d]of Object.entries(v.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!Array.isArray(d.awards)||new Set(d.awards).size!==d.awards.length||d.awards.some(x=>!missions.some(m=>m[0]===x))||!d.checks)throw Error()}for(let r of v.spent)if(![100,200,300].includes(r.cost)||typeof r.label!=='string')throw Error();for(let k of Object.keys(empty().settings))if(typeof v.settings[k]!=='string')throw Error();let earned=Object.values(v.days).reduce((n,d)=>n+d.awards.length,0);if(v.spent.reduce((n,r)=>n+r.cost,0)>earned)throw Error()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelector('.close').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#settings').onclick=settings;document.querySelector('#rules').onclick=()=>modal('<h2>Small wins. Big adventures.</h2><p>Each of your five missions earns one point per day: up to 5 a day and 35 a week. Weeks run Monday through Sunday.</p><p><b>25 weekly points</b> unlock a Gym Badge and a small Target toy within your family’s budget. The toy costs no points.</p><p>Every earned point also goes into your Adventure Bank, even during weeks below 25. Spend 100 on a Local Adventure, 200 on a Super Adventure, or save 300 for a Legendary Adventure. Parents approve the outing and date.</p><p>Points never expire and are never taken away. A missed mission earns zero; tomorrow is a fresh start. Reminders and help are allowed. Review the system together after two practice weeks.</p>');render();
